        "IsHard" boolean NOT NULL DEFAULT TRUE,
        "Weight" integer NOT NULL DEFAULT 100,
        "DayOfWeek" integer,
        "SlotNumber" integer,
        "Value" character varying(500),
        "IsActive" boolean NOT NULL DEFAULT TRUE,
        "CreatedAt" timestamp with time zone NOT NULL DEFAULT (CURRENT_TIMESTAMP),
        "UpdatedAt" timestamp with time zone,
        CONSTRAINT "PK_ScheduleConstraints" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_ScheduleConstraints_Organizations_OrganizationId" FOREIGN KEY ("OrganizationId") REFERENCES "Organizations" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

