    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260723094656_AddTeacherNumberAliasAndInfo') THEN
    ALTER TABLE "Teachers" ADD "TeacherNumber" integer NOT NULL DEFAULT 0;
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260723094656_AddTeacherNumberAliasAndInfo') THEN
    WITH numbered_teachers AS
    (
        SELECT
            "Id",
            ROW_NUMBER() OVER
            (
                PARTITION BY "OrganizationId"
                ORDER BY "Id"
            ) AS teacher_number
        FROM "Teachers"
    )
    UPDATE "Teachers" AS teacher
    SET
        "TeacherNumber" = numbered.teacher_number,
        "Alias" = 'T' || numbered.teacher_number
    FROM numbered_teachers AS numbered
    WHERE teacher."Id" = numbered."Id";
    END IF;
END $EF$;

