DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260724084833_AddResourceUnavailability') THEN
    CREATE TABLE "ClassGroupUnavailabilities" (
